import {esc,fmt} from '../../ui/format.js';
import {TYPES,FIELDS,PROCESS,POOLS,effective} from '../../core/model.js';
import {DIAGRAMS,expandedNeeds,modelAudit} from '../../core/mbse.js';
import {RELATIONS} from '../../core/model.js';
export function scenariosView(ctx){const {m,result,baseline,search}=ctx;const n=id=>m.nodes.find(n=>n.id===id);return `<h1>Scenarii & baseline</h1><div class="panel"><p>Fixează rezultatul și modelul, schimbă o variabilă sau o alocare, apoi simulează din nou. Comparația se face la același orizont, seed și număr de replicări.</p><div class="row"><button data-action="baseline" class="primary" ${result?'':'disabled'}>Fixează baseline</button><button data-action="restore" ${baseline?'':'disabled'}>Restaurează baseline</button><button data-action="comparison" ${baseline?'':'disabled'}>Export comparație</button></div>${baseline?`<table><thead><tr><th>Indicator</th><th>Baseline</th><th>Actual</th><th>Δ</th></tr></thead><tbody>${[['Medie produse bune',baseline.result.mean,result?.mean],['WIP (replicarea 1)',baseline.result.first.wip,result?.first.wip],['Cost modelat (replicarea 1)',baseline.result.first.totalCost,result?.first.totalCost]].map(([label,a,b])=>`<tr><td>${label}</td><td>${fmt(a)}</td><td>${fmt(b)}</td><td>${b==null?'—':fmt(b-a)}</td></tr>`).join('')}</tbody></table><p class="small muted">Baseline-ul și rezultatele sunt în memoria sesiunii. Exportă pentru arhivare.</p>${result&&JSON.stringify(baseline.model.settings)!==JSON.stringify(m.settings)?'<div class="notice">Setările diferă: rezultatele nu izolează schimbarea de design.</div>':''}`:'<div class="empty">Rulează modelul pentru primul baseline.</div>'}</div>`}
